import numpy as np
import os
try:
    from scipy.optimize import linprog
except Exception:
    linprog = None

N = 32
R_MIN = 1e-8
PAIR_EPS = 5e-16  # float-safe pair margin in finalize

def _pairs(n=N):
    return [(i, j) for i in range(n) for j in range(i+1, n)]
PAIRS_ALL = _pairs()

# ---------- Geometry ----------
def _dist(a, b):
    d = a - b
    return float(np.sqrt(np.dot(d, d)))

def _lp_dist(a, b, p):
    d = np.abs(a - b)
    return float((d[0]**p + d[1]**p) ** (1.0/p))

# ---------- Finalize ----------
def _finalize_zero_tol(C, r, pair_eps=PAIR_EPS, max_passes=3):
    n = C.shape[0]
    r = np.asarray(r, dtype=float).copy()
    x = C[:, 0]; y = C[:, 1]
    for i in range(n):
        if x[i] - r[i] < 0.0: r[i] = max(R_MIN, min(r[i], x[i]))
        if 1.0 - x[i] - r[i] < 0.0: r[i] = max(R_MIN, min(r[i], 1.0 - x[i]))
        if y[i] - r[i] < 0.0: r[i] = max(R_MIN, min(r[i], y[i]))
        if 1.0 - y[i] - r[i] < 0.0: r[i] = max(R_MIN, min(r[i], 1.0 - y[i]))
    for _ in range(max_passes):
        changed = False
        for (i, j) in PAIRS_ALL:
            dij = _dist(C[i], C[j])
            cap = dij - pair_eps
            s = r[i] + r[j]
            if s > cap:
                need = s - cap
                di = min(0.5*need, max(0.0, r[i] - R_MIN))
                dj = min(0.5*need, max(0.0, r[j] - R_MIN))
                rem = need - (di + dj)
                if rem > 0:
                    take = min(rem, max(0.0, r[i] - R_MIN - di)); di += take; rem -= take
                if rem > 0:
                    take = min(rem, max(0.0, r[j] - R_MIN - dj)); dj += take; rem -= take
                r[i] = max(R_MIN, r[i] - di)
                r[j] = max(R_MIN, r[j] - dj)
                changed = True
        if not changed:
            break
    return r

# ---------- Exact zero-slack radii LP ----------
def _solve_radii_zero_slack(C):
    n = C.shape[0]
    x = C[:, 0]; y = C[:, 1]
    rows = []; rhs = []
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(x[i])))
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(1.0 - x[i])))
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(y[i])))
    for i in range(n):
        a = np.zeros(n); a[i] = 1.0; rows.append(a); rhs.append(max(0.0, float(1.0 - y[i])))
    for (i, j) in PAIRS_ALL:
        a = np.zeros(n); a[i] = 1.0; a[j] = 1.0
        rows.append(a); rhs.append(max(0.0, _dist(C[i], C[j])))
    A_ub = np.vstack(rows); b_ub = np.array(rhs)
    c = -np.ones(n)
    bounds = [(R_MIN, None) for _ in range(n)]
    if linprog is None:
        bnd = np.minimum.reduce([x, 1.0-x, y, 1.0-y])
        r = np.maximum(R_MIN, bnd)
        return _finalize_zero_tol(C, r), False
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not res.success:
        bnd = np.minimum.reduce([x, 1.0-x, y, 1.0-y])
        r = np.maximum(R_MIN, 0.99*bnd)
        return _finalize_zero_tol(C, r), False
    r = np.maximum(R_MIN, np.array(res.x, dtype=float))
    return _finalize_zero_tol(C, r), True

# ---------- Lp-based active pairs and weights ----------
def _active_pairs_lp(C, r, p, K_mult):
    if K_mult is None:
        return PAIRS_ALL
    K = int(max(1, K_mult * C.shape[0]))
    rec = []
    for (i, j) in PAIRS_ALL:
        s = _lp_dist(C[i], C[j], p) - (r[i] + r[j])
        rec.append((s, i, j))
    rec.sort(key=lambda t: t[0])
    return [(i, j) for (_, i, j) in (rec if K >= len(rec) else rec[:K])]

def _circle_weights_lp(C, r, p):
    n = C.shape[0]
    x = C[:, 0]; y = C[:, 1]
    bslack = np.minimum.reduce([x - r, 1.0 - x - r, y - r, 1.0 - y - r])
    ps = np.full(n, np.inf, dtype=float)
    for (i, j) in PAIRS_ALL:
        sij = _lp_dist(C[i], C[j], p) - (r[i] + r[j])
        ps[i] = min(ps[i], sij); ps[j] = min(ps[j], sij)
    tight = np.minimum(bslack, ps)
    tight = np.maximum(tight, 1e-9)
    w = 1.0 / tight
    w /= float(np.sum(w))
    return w

# ---------- Weighted SCP-LP step ----------
def _build_step(C0, active_pairs, tau, w):
    n = C0.shape[0]; m = 3*n
    rows = []; rhs = []
    for (i, j) in active_pairs:
        d0 = C0[i] - C0[j]
        n0 = float(np.linalg.norm(d0))
        u = np.array([1.0, 0.0]) if n0 < 1e-16 else d0 / n0
        row = np.zeros(m)
        row[2*n + i] += 1.0; row[2*n + j] += 1.0
        row[i] -= u[0]; row[j] += u[0]
        row[n+i] -= u[1]; row[n+j] += u[1]
        rows.append(row); rhs.append(0.0)
    for i in range(n):
        row = np.zeros(m); row[2*n+i] += 1.0; row[i] -= 1.0
        rows.append(row); rhs.append(0.0)
        row = np.zeros(m); row[2*n+i] += 1.0; row[i] += 1.0
        rows.append(row); rhs.append(1.0)
        row = np.zeros(m); row[2*n+i] += 1.0; row[n+i] -= 1.0
        rows.append(row); rhs.append(0.0)
        row = np.zeros(m); row[2*n+i] += 1.0; row[n+i] += 1.0
        rows.append(row); rhs.append(1.0)
    A_ub = np.vstack(rows); b_ub = np.array(rhs)
    x0 = C0[:, 0]; y0 = C0[:, 1]
    x_lb = np.maximum(0.0, x0 - tau); x_ub = np.minimum(1.0, x0 + tau)
    y_lb = np.maximum(0.0, y0 - tau); y_ub = np.minimum(1.0, y0 + tau)
    bounds = [(float(x_lb[i]), float(x_ub[i])) for i in range(n)]
    bounds += [(float(y_lb[i]), float(y_ub[i])) for i in range(n)]
    bounds += [(R_MIN, None) for _ in range(n)]
    c = np.zeros(m); c[2*n:] = -w
    return A_ub, b_ub, bounds, c

def _step_weighted(C0, r0, tau, w, active_pairs):
    if linprog is None:
        return None, None, None
    n = C0.shape[0]
    A_ub, b_ub, bounds, c = _build_step(C0, active_pairs, tau, w)
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not res.success:
        return None, None, res
    x = res.x
    X = x[:n]; Y = x[n:2*n]; R_lin = x[2*n:]
    C_new = np.stack([X, Y], axis=1)
    return C_new, R_lin, res

# ---------- Candidate optimize ----------
def _candidate_optimize(Cinit, p, K_mult, max_outer=18, verbose=False):
    C = Cinit.copy()
    r, _ = _solve_radii_zero_slack(C)
    best_C = C.copy(); best_r = r.copy(); best_s = float(np.sum(r))
    if verbose:
        print(f"[wscp-sweep] start s={best_s:.15f} p={p} K={K_mult}")

    tau = 0.05; min_tau = 1e-3; no_imp = 0; patience = 8
    alphas = [1.0, 0.7, 0.5, 0.35, 0.2]
    for it in range(max_outer):
        w = _circle_weights_lp(C, r, p)
        active = _active_pairs_lp(C, r, p, K_mult)
        step = _step_weighted(C, r, tau, w, active)
        if step[0] is None:
            tau *= 0.6
            if tau < min_tau: break
            continue
        C_lin, _Rlin, _ = step
        d = C_lin - C
        best_local_s = -1.0; best_local = None
        for a in alphas:
            C_try = np.clip(C + a*d, 0.0, 1.0)
            r_try, _ = _solve_radii_zero_slack(C_try)
            s = float(np.sum(r_try))
            if s > best_local_s:
                best_local_s = s
                best_local = (C_try, r_try)
        if best_local is not None and best_local_s > best_s + 1e-9:
            C, r = best_local
            best_C = C.copy(); best_r = r.copy(); best_s = best_local_s
            tau = min(0.12, tau*1.15)
            no_imp = 0
            if verbose:
                print(f"[wscp-sweep] it={it:02d} accept s={best_s:.15f} tau={tau:.4f}")
        else:
            tau *= 0.6; no_imp += 1
            if verbose:
                print(f"[wscp-sweep] it={it:02d} reject s={best_s:.15f} tau={tau:.4f}")
            if tau < min_tau or no_imp >= patience:
                break
    return best_C, best_r, best_s

# ---------- Seeds ----------
def _seed_storage_best():
    try:
        C = np.load("storage/verity/best_centers.npy")
        if isinstance(C, np.ndarray) and C.shape == (N, 2):
            return np.clip(C.astype(float), 0.0, 1.0)
    except Exception:
        pass
    return None

def _seed_storage_best_jitter(amplitude=0.001, seed=9731):
    C = _seed_storage_best()
    if C is None: return None
    rng = np.random.default_rng(seed)
    jit = rng.uniform(-amplitude, amplitude, size=C.shape)
    return np.clip(C + jit, 0.0, 1.0)

def _fallback_grid():
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 6)
    centers = []
    for ix, x in enumerate(xs):
        for iy, y in enumerate(ys):
            if (ix in (0, 5)) and (iy in (0, 5)):
                continue
            centers.append([x, y])
    C = np.array(centers, dtype=float)
    assert C.shape == (32, 2)
    return C

# ---------- Persist gate ----------
def _current_best_sum():
    try:
        r = np.load("storage/verity/best_radii.npy")
        if isinstance(r, np.ndarray) and r.shape == (N,):
            return float(np.sum(r))
    except Exception:
        pass
    return -np.inf

def construct_packing() -> tuple:
    seed_set = []
    Cb = _seed_storage_best()
    if Cb is not None:
        seed_set.append(("storage-best", Cb))
        Cj = _seed_storage_best_jitter()
        if Cj is not None:
            seed_set.append(("storage-best-jitter", Cj))
    else:
        seed_set.append(("grid-36minus4", _fallback_grid()))

    p_list = [1.2, 1.4, 1.6, 2.0]
    K_list = [3, 4, 8, None]  # None -> all pairs
    best_sum = -1.0; best_C = None; best_r = None

    for seed_name, C0 in seed_set:
        for p in p_list:
            for Kmult in K_list:
                C_opt, r_opt, s_opt = _candidate_optimize(C0, p, Kmult, max_outer=18, verbose=False)
                print(f"[wscp-sweep] seed={seed_name} p={p} K={Kmult} sum={s_opt:.15f}")
                if s_opt > best_sum:
                    best_sum = s_opt; best_C = C_opt; best_r = r_opt

    # gated persist: only if improvement over stored best
    try:
        os.makedirs("storage/verity", exist_ok=True)
        prev = _current_best_sum()
        if best_sum > prev + 1e-12:
            np.save("storage/verity/best_centers.npy", best_C)
            np.save("storage/verity/best_radii.npy", best_r)
    except Exception:
        pass

    return np.array(best_C, dtype=float), np.array(best_r, dtype=float)
